        t_out = max(1, tensor.shape[2] // factor)
        h_out = max(1, tensor.shape[3] // factor)
        w_out = max(1, tensor.shape[4] // factor)
        return F.interpolate(tensor, size=(t_out, h_out, w_out), mode=mode, align_corners=False)

